// ═══════════════════════════════════════════════════════════════════
// python_testbench.v — randomized testbench driven by run_random.py
//
// Reads test/inputs.hex (generated by run_random.py), runs each test
// case through the DUT, and prints outputs for Python to compare.
// Do not compile manually — use run_random.py or run.sh.
// ═══════════════════════════════════════════════════════════════════

`ifndef N_CASES
`define N_CASES 10
`endif

module python_testbench;

    reg signed [15:0]
        in_re0,  in_im0,  in_re1,  in_im1,
        in_re2,  in_im2,  in_re3,  in_im3,
        in_re4,  in_im4,  in_re5,  in_im5,
        in_re6,  in_im6,  in_re7,  in_im7,
        in_re8,  in_im8,  in_re9,  in_im9,
        in_re10, in_im10, in_re11, in_im11,
        in_re12, in_im12, in_re13, in_im13,
        in_re14, in_im14, in_re15, in_im15;

    wire signed [19:0]
        out_re0,  out_im0,  out_re1,  out_im1,
        out_re2,  out_im2,  out_re3,  out_im3,
        out_re4,  out_im4,  out_re5,  out_im5,
        out_re6,  out_im6,  out_re7,  out_im7,
        out_re8,  out_im8,  out_re9,  out_im9,
        out_re10, out_im10, out_re11, out_im11,
        out_re12, out_im12, out_re13, out_im13,
        out_re14, out_im14, out_re15, out_im15;

`ifdef USE_FLAT
    FFT_16pt_flat #(.DW(16)) uut (
`else
    FFT_16pt      #(.DW(16)) uut (
`endif
        .in_re0(in_re0),   .in_im0(in_im0),
        .in_re1(in_re1),   .in_im1(in_im1),
        .in_re2(in_re2),   .in_im2(in_im2),
        .in_re3(in_re3),   .in_im3(in_im3),
        .in_re4(in_re4),   .in_im4(in_im4),
        .in_re5(in_re5),   .in_im5(in_im5),
        .in_re6(in_re6),   .in_im6(in_im6),
        .in_re7(in_re7),   .in_im7(in_im7),
        .in_re8(in_re8),   .in_im8(in_im8),
        .in_re9(in_re9),   .in_im9(in_im9),
        .in_re10(in_re10), .in_im10(in_im10),
        .in_re11(in_re11), .in_im11(in_im11),
        .in_re12(in_re12), .in_im12(in_im12),
        .in_re13(in_re13), .in_im13(in_im13),
        .in_re14(in_re14), .in_im14(in_im14),
        .in_re15(in_re15), .in_im15(in_im15),
        .out_re0(out_re0),   .out_im0(out_im0),
        .out_re1(out_re1),   .out_im1(out_im1),
        .out_re2(out_re2),   .out_im2(out_im2),
        .out_re3(out_re3),   .out_im3(out_im3),
        .out_re4(out_re4),   .out_im4(out_im4),
        .out_re5(out_re5),   .out_im5(out_im5),
        .out_re6(out_re6),   .out_im6(out_im6),
        .out_re7(out_re7),   .out_im7(out_im7),
        .out_re8(out_re8),   .out_im8(out_im8),
        .out_re9(out_re9),   .out_im9(out_im9),
        .out_re10(out_re10), .out_im10(out_im10),
        .out_re11(out_re11), .out_im11(out_im11),
        .out_re12(out_re12), .out_im12(out_im12),
        .out_re13(out_re13), .out_im13(out_im13),
        .out_re14(out_re14), .out_im14(out_im14),
        .out_re15(out_re15), .out_im15(out_im15)
    );

    // Input storage: N_CASES test cases × 16 samples (real only)
    reg [15:0] inputs [0:`N_CASES*16-1];
    integer i;

    initial begin
        $readmemh("test/inputs.hex", inputs);

        for (i = 0; i < `N_CASES; i = i + 1) begin
            // Load real inputs; imaginary parts are always 0
            in_re0  = inputs[i*16+ 0]; in_im0  = 0;
            in_re1  = inputs[i*16+ 1]; in_im1  = 0;
            in_re2  = inputs[i*16+ 2]; in_im2  = 0;
            in_re3  = inputs[i*16+ 3]; in_im3  = 0;
            in_re4  = inputs[i*16+ 4]; in_im4  = 0;
            in_re5  = inputs[i*16+ 5]; in_im5  = 0;
            in_re6  = inputs[i*16+ 6]; in_im6  = 0;
            in_re7  = inputs[i*16+ 7]; in_im7  = 0;
            in_re8  = inputs[i*16+ 8]; in_im8  = 0;
            in_re9  = inputs[i*16+ 9]; in_im9  = 0;
            in_re10 = inputs[i*16+10]; in_im10 = 0;
            in_re11 = inputs[i*16+11]; in_im11 = 0;
            in_re12 = inputs[i*16+12]; in_im12 = 0;
            in_re13 = inputs[i*16+13]; in_im13 = 0;
            in_re14 = inputs[i*16+14]; in_im14 = 0;
            in_re15 = inputs[i*16+15]; in_im15 = 0;
            #10;

            // Print outputs — parsed by run_random.py
            // Format: OUT <case> <bin> <re> <im>
            $display("OUT %0d  0 %0d %0d", i, $signed(out_re0),  $signed(out_im0));
            $display("OUT %0d  1 %0d %0d", i, $signed(out_re1),  $signed(out_im1));
            $display("OUT %0d  2 %0d %0d", i, $signed(out_re2),  $signed(out_im2));
            $display("OUT %0d  3 %0d %0d", i, $signed(out_re3),  $signed(out_im3));
            $display("OUT %0d  4 %0d %0d", i, $signed(out_re4),  $signed(out_im4));
            $display("OUT %0d  5 %0d %0d", i, $signed(out_re5),  $signed(out_im5));
            $display("OUT %0d  6 %0d %0d", i, $signed(out_re6),  $signed(out_im6));
            $display("OUT %0d  7 %0d %0d", i, $signed(out_re7),  $signed(out_im7));
            $display("OUT %0d  8 %0d %0d", i, $signed(out_re8),  $signed(out_im8));
            $display("OUT %0d  9 %0d %0d", i, $signed(out_re9),  $signed(out_im9));
            $display("OUT %0d 10 %0d %0d", i, $signed(out_re10), $signed(out_im10));
            $display("OUT %0d 11 %0d %0d", i, $signed(out_re11), $signed(out_im11));
            $display("OUT %0d 12 %0d %0d", i, $signed(out_re12), $signed(out_im12));
            $display("OUT %0d 13 %0d %0d", i, $signed(out_re13), $signed(out_im13));
            $display("OUT %0d 14 %0d %0d", i, $signed(out_re14), $signed(out_im14));
            $display("OUT %0d 15 %0d %0d", i, $signed(out_re15), $signed(out_im15));
        end
        $finish;
    end
endmodule